import { projectChainEntries, projectRoleAddresses } from "./projects.js";

const REGISTRY_ROLES = ["treasury", "holdings"];
const CONFIDENCE_RE = /\b(high|medium|low)\b/i;
const SOLSCAN_URL_RE = /https:\/\/solscan\.io\/[^\s·)]+/;
const DEFAULT_CONFIDENCE = "low";
const REGISTRY_DESCRIPTION =
  "Registry for the gated Wallet flows report. Generated by scripts/init-forensics-registry.js from the project's config contracts; edit labels and confidence here.";

/** Confidence word in a contracts{} `$comment`; "low" when absent. */
export function parseConfidence(comment) {
  if (typeof comment !== "string") return DEFAULT_CONFIDENCE;
  const match = CONFIDENCE_RE.exec(comment);
  return match ? match[1].toLowerCase() : DEFAULT_CONFIDENCE;
}

function parseSource(comment, config) {
  const match = typeof comment === "string" ? SOLSCAN_URL_RE.exec(comment) : null;
  return match ? match[0] : `config/projects/${config.slug}.json`;
}

function buildLabel(contract, name, role, address, config) {
  const explicit = contract.label ?? contract.name;
  if (explicit !== undefined) return explicit;
  const shortAddress = `${address.slice(0, 4)}…${address.slice(-4)}`;
  return `${config.ticker ?? config.slug} ${role} ${shortAddress}`;
}

function buildWallet({ entry, contract, chainKey, config }) {
  const { name, address, role } = entry;
  return {
    address,
    label: buildLabel(contract, name, role, address, config),
    group: role,
    entityClass: role,
    source: parseSource(contract.$comment, config),
    confidence: parseConfidence(contract.$comment),
    chains: [chainKey],
  };
}

function contractLookup(config) {
  const byChain = new Map();
  for (const chain of projectChainEntries(config)) {
    byChain.set(chain.key, chain.contracts ?? {});
  }
  return byChain;
}

/**
 * Known-wallet rows for the forensics registry, one per non-retail address
 * (treasury + holdings roles), de-duplicated by exact address string (first wins).
 * Pure: no I/O.
 */
export function deriveRegistry(config, { chainKey } = {}) {
  const contractsByChain = contractLookup(config);
  const roleAddresses = projectRoleAddresses(config, { roles: REGISTRY_ROLES });
  const seen = new Set();
  const knownWallets = [];

  for (const [key, entries] of Object.entries(roleAddresses)) {
    if (chainKey !== undefined && key !== chainKey) continue;
    const contracts = contractsByChain.get(key) ?? {};
    for (const entry of entries) {
      if (seen.has(entry.address)) continue;
      seen.add(entry.address);
      knownWallets.push(buildWallet({ entry, contract: contracts[entry.name] ?? {}, chainKey: key, config }));
    }
  }

  return {
    version: 1,
    description: REGISTRY_DESCRIPTION,
    knownWallets,
    botCluster: null,
    watchedSellers: [],
    extraCex: [],
    extraDex: [],
  };
}
